  let p=vec3i(id);let a=loadAt(p);let g=runoffGeometry(p);
  var f=vec3f(faceFlux(p,a,g,vec3i(1,0,0),0),faceFlux(p,a,g,vec3i(0,1,0),1),faceFlux(p,a,g,vec3i(0,0,1),2));
