    if(abs(normal.x)>abs(normal.y)&&abs(normal.x)>abs(normal.z)){front=vec3i(select(-1,1,normal.x>=0.),0,0);}
    else if(abs(normal.y)>abs(normal.z)){front=vec3i(0,select(-1,1,normal.y>=0.),0);}
